CREATE TABLE public.folha_pessoas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), nome text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.folha_pessoas TO service_role;
ALTER TABLE public.folha_pessoas ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.folha_colaboradores ADD COLUMN pessoa_id uuid REFERENCES public.folha_pessoas(id);
INSERT INTO public.folha_pessoas(id,nome) SELECT id,nome FROM public.folha_colaboradores;
UPDATE public.folha_colaboradores SET pessoa_id=id WHERE pessoa_id IS NULL;
CREATE UNIQUE INDEX folha_pessoa_unidade_unique ON public.folha_colaboradores(pessoa_id,unidade_id);
ALTER TABLE public.folha_colaboradores DROP CONSTRAINT folha_colaboradores_tipo_check;
ALTER TABLE public.folha_colaboradores ADD CONSTRAINT folha_colaboradores_tipo_check CHECK(tipo IN ('CLT','ESTAGIARIO','SEM_CONTRATO'));
ALTER TABLE public.folha_permissoes DROP CONSTRAINT folha_permissoes_acao_check;
ALTER TABLE public.folha_permissoes ADD CONSTRAINT folha_permissoes_acao_check CHECK(acao IN ('ver','lancar','colaboradores','fechar','confirmar','desfazer','regras','importar','documentos','dados_pessoais'));
CREATE OR REPLACE FUNCTION public.folha_minhas_permissoes(_unidade_id uuid) RETURNS text[] LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT COALESCE(array_agg(a),'{}') FROM unnest(ARRAY['ver','lancar','colaboradores','fechar','confirmar','desfazer','regras','importar','documentos','dados_pessoais','reabrir']) a WHERE CASE WHEN a='reabrir' THEN public.has_role(auth.uid(),'admin') WHEN a='regras' THEN public.folha_pode_global(auth.uid(),a) ELSE public.folha_pode(auth.uid(),_unidade_id,a) END $$;
CREATE POLICY folha_colab_dados_privados ON public.folha_colaboradores AS RESTRICTIVE FOR SELECT TO authenticated USING(public.folha_pode(auth.uid(),unidade_id,'dados_pessoais'));
CREATE POLICY folha_pag_dados_privados ON public.folha_pagamentos AS RESTRICTIVE FOR SELECT TO authenticated USING(public.folha_pode(auth.uid(),unidade_id,'dados_pessoais'));
CREATE POLICY folha_comp_dados_privados ON public.folha_competencias AS RESTRICTIVE FOR SELECT TO authenticated USING(public.folha_pode(auth.uid(),unidade_id,'dados_pessoais'));
CREATE POLICY folha_aud_dados_privados ON public.folha_auditoria AS RESTRICTIVE FOR SELECT TO authenticated USING(CASE WHEN unidade_id IS NULL THEN public.folha_pode_global(auth.uid(),'dados_pessoais') ELSE public.folha_pode(auth.uid(),unidade_id,'dados_pessoais') END);
CREATE OR REPLACE FUNCTION public.folha_colaborador_identidade() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN IF NEW.pessoa_id IS NULL THEN INSERT INTO public.folha_pessoas(nome) VALUES(NEW.nome) RETURNING id INTO NEW.pessoa_id; END IF; IF NEW.tipo='SEM_CONTRATO' AND NEW.ativo THEN RAISE EXCEPTION 'Sem contrato: ativação aguarda regra de cálculo'; END IF; IF auth.uid() IS NOT NULL AND ((TG_OP='INSERT' AND (NEW.cpf IS NOT NULL OR NEW.pix IS NOT NULL)) OR (TG_OP='UPDATE' AND (NEW.cpf IS DISTINCT FROM OLD.cpf OR NEW.pix IS DISTINCT FROM OLD.pix))) AND NOT public.folha_pode(auth.uid(),NEW.unidade_id,'dados_pessoais') THEN RAISE EXCEPTION 'Sem permissão explícita para CPF e PIX'; END IF; IF TG_OP='UPDATE' AND NEW.unidade_id IS DISTINCT FROM OLD.unidade_id THEN RAISE EXCEPTION 'Crie vínculo separado: unidade do cadastro é imutável'; END IF; IF TG_OP='UPDATE' AND NEW.pessoa_id IS DISTINCT FROM OLD.pessoa_id AND EXISTS(SELECT 1 FROM public.folha_pagamentos WHERE colaborador_id=OLD.id) THEN RAISE EXCEPTION 'Vínculo com pagamentos históricos não pode trocar identidade'; END IF; RETURN NEW; END $$;
CREATE TRIGGER folha_colaborador_identidade BEFORE INSERT OR UPDATE ON public.folha_colaboradores FOR EACH ROW EXECUTE FUNCTION public.folha_colaborador_identidade();
CREATE OR REPLACE FUNCTION public.folha_validar_ajustes() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE a jsonb; BEGIN IF NOT EXISTS(SELECT 1 FROM public.folha_colaboradores WHERE id=NEW.colaborador_id AND unidade_id=NEW.unidade_id AND tipo<>'SEM_CONTRATO') THEN RAISE EXCEPTION 'Colaborador fora da unidade ou vínculo sem regra'; END IF; IF jsonb_typeof(COALESCE(NEW.dados->'ajustes','[]'::jsonb))<>'array' THEN RAISE EXCEPTION 'Ajustes inválidos'; END IF; FOR a IN SELECT * FROM jsonb_array_elements(COALESCE(NEW.dados->'ajustes','[]'::jsonb)) LOOP IF length(trim(COALESCE(a->>'descricao','')))=0 OR a->>'tipo' NOT IN ('adicional','desconto') OR a->>'id' IS NULL OR a->>'valor' IS NULL OR (a->>'valor')::numeric<0 OR (a->>'valor')::numeric>1000000 THEN RAISE EXCEPTION 'Adicional/desconto exige descrição, tipo e valor válido'; END IF; END LOOP; RETURN NEW; END $$;
CREATE TRIGGER folha_ajustes_validos BEFORE INSERT OR UPDATE ON public.folha_lancamentos FOR EACH ROW EXECUTE FUNCTION public.folha_validar_ajustes();
CREATE OR REPLACE FUNCTION public.folha_auditar() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE r jsonb=to_jsonb(COALESCE(NEW,OLD)); u uuid; BEGIN u=COALESCE(auth.uid(),NULLIF(current_setting('folha.usuario',true),'')::uuid); INSERT INTO public.folha_auditoria(tabela,registro_id,unidade_id,competencia,acao,antes,depois,user_id) VALUES(TG_TABLE_NAME,NULLIF(r->>'id','')::uuid,NULLIF(r->>'unidade_id','')::uuid,r->>'competencia',TG_OP,CASE WHEN TG_OP<>'INSERT' THEN to_jsonb(OLD) END,CASE WHEN TG_OP<>'DELETE' THEN to_jsonb(NEW) END,u); RETURN COALESCE(NEW,OLD); END $$;
COMMENT ON COLUMN public.folha_colaboradores.pessoa_id IS 'Identidade estável; colaborador id preserva o vínculo e histórico por unidade. Sem fusão automática por CPF ou nome.';